document.addEventListener('DOMContentLoaded', function () {
const approveBtn = document.querySelector('.flash-button');

if (approveBtn) {
approveBtn.addEventListener('click', function () {

// approveBtn.setAttribute('approve-action', 'open_app');
// console.log("approve-action updated to open_app");

window.kwipped_approve.embedded_app.app_reference.clear_items();
});
}
});

window.kwipped_approve.add_listener = setInterval(function(){
    if(window.kwipped_approve && window.kwipped_approve.embedded_app && window.kwipped_approve.embedded_app.app_reference){
        clearInterval(window.kwipped_approve.add_listener);
        //Add listener here.
        window.kwipped_approve.embedded_app.app_reference.add_listener(function(message){
            if(message.action=="app_submitted"){
            console.log("This is a submitted application:",message.data);

            const orderId = document.querySelector('#approve_order_id')?.getAttribute('data-order-id');
            if (!orderId) {
                console.error("Order ID not found for APPROVE submission.");
                return;
            }

            fetch(`/approve/application_submitted/${orderId}`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(message.data)
            })
            .then(res => res.json())
            .then(data => console.log("Approve submission logged:", data))
            .catch(err => console.error("Approve logging failed:", err));
            }
        });

    }
},100);
